gb33(){return"Zuhause"},
gb32(){return"Weg"},
gb31(){return"Spannung"},
gaQV(){return"Harmonie"},
gaR4(){return"Harmonie analysieren"},
gD9(){return"Untersuchen (Note antippen)"},
gaQU(){return"Form"},
